// Append further secondary practice without changing any of the first 10,000 saved question keys.
const EXTENSION_STAGES=[{level:51,tier:9,year:9,name:'Year 9 · Explorer'},{level:58,tier:10,year:9,name:'Year 9 · Advanced reasoning'},{level:65,tier:11,year:10,name:'Year 10 · Explorer'},{level:73,tier:12,year:10,name:'Year 10 · Advanced reasoning'},{level:80,tier:13,year:11,name:'Year 11 · Senior explorer'},{level:85,tier:14,year:11,name:'Year 11 · Advanced reasoning'},{level:90,tier:15,year:12,name:'Year 12 · Senior challenge'},{level:96,tier:16,year:12,name:'Year 12 · Advanced reasoning'},{level:100,tier:17,year:12,name:'Year 12 · Level 100 mastery'}];
QUESTION_STAGES.push(...EXTENSION_STAGES);
for(const year of [10,11,12])for(const q of SENIOR_BANK[year]){const id=['Mathematics','Statistics'].includes(q.field)?'maths':q.field==='Biology'?'biology':q.field==='Chemistry'?'chemistry':q.field==='English'?'english':q.field==='History'?'history':q.field==='Civics'?'civics':q.field==='Economics'?'economics':'science',tier=year===10?11:year===11?13:15;BANK[id].push([q.prompt,[...q.options],0,q.why,null,null,q.family,tier,year])}
const YEAR9_CONCEPTS=[
['science','Why does energy transfer between trophic levels limit food-chain length?',['Much transferred energy is used in life processes and dissipated as heat','Energy is created only by top predators','Every level receives identical usable energy','Producers do not need energy'],'Only some energy becomes biomass available to the next trophic level. Transfers to the surroundings limit energy available higher in a food chain.'],
['chemistry','What determines an element’s atomic number?',['Its number of protons','Its number of neutrons only','Its mass in grams','The number of chemical bonds in a sample'],'Atomic number is the proton count in an atomic nucleus. Changing neutron count produces isotopes of the same element.'],
['biology','What is the main role of meiosis in sexual reproduction?',['Producing cells with half the usual chromosome number','Producing genetically identical body cells only','Doubling chromosome number in every generation','Removing all genetic material'],'Meiosis reduces chromosome number. Fusion of gametes can then restore the usual number at fertilisation.'],
['english','A writer repeats “we must act” at the start of three successive sentences. Which term describes this pattern?',['Anaphora','Onomatopoeia','A footnote','A stage direction'],'Anaphora repeats wording at the beginnings of successive clauses or sentences, often building emphasis and rhythm.'],
['history','Why should a historian distinguish immediate triggers from long-term causes?',['An event can result from several causes operating over different timescales','Every event has exactly one cause','Triggers always make long-term conditions irrelevant','Chronology prevents the use of evidence'],'A trigger can set an event in motion while long-standing conditions help explain why it occurred and how it developed.'],
['geography','Why can a food-supply decision be evaluated at local and global scales?',['Production, trade and environmental effects connect places at different scales','Food production is isolated from trade','Local effects always equal global effects','Maps cannot represent supply chains'],'Supply chains link farms, markets, consumers and environments across places. A decision can have different effects at different scales.']
];
for(const[id,prompt,options,why]of YEAR9_CONCEPTS)BANK[id].push([prompt,options,0,why,null,null,'year9-concept',9,9]);
function extensionNumber(id,year,tier,prompt,n,why,family){BANK[id].push([prompt,[n,n+1,n-1,n+3].map(formatNumber),0,why,null,null,family,tier,year])}
let extensionSerial=0;
while(Object.values(BANK).reduce((n,a)=>n+a.length,0)<12000){const n=extensionSerial++,v=n%16,k=Math.floor(n/16),a=k+3,b=2+k%7;
 if(v===0)extensionNumber('maths',9,9,`Expand ${b}(x + ${a}). What is the constant term?`,a*b,`Distribute ${b}: ${b}x + ${a*b}. The term without x is ${a*b}.`,'expand-constant');
 if(v===1)extensionNumber('maths',9,10,`A line has equation y = ${b}x − ${a}. What is y when x = ${a+1}?`,b*(a+1)-a,`Substitute x = ${a+1}: y = ${b} × ${a+1} − ${a} = ${b*(a+1)-a}.`,'linear-substitution');
 if(v===2)extensionNumber('science',9,9,`A circuit has resistance ${a} Ω and current ${b} A. Using V = IR, what is the voltage in volts?`,a*b,`V = I × R = ${b} × ${a} = ${a*b} V.`,'ohms-law');
 if(v===3)extensionNumber('chemistry',9,10,`An isotope has ${a} protons and ${a+b} neutrons. What is its mass number?`,2*a+b,`Mass number counts protons plus neutrons: ${a} + ${a+b} = ${2*a+b}. This is a supplied-number model, not a claim that every such isotope is stable.`,'mass-number');
 if(v===4)extensionNumber('maths',10,11,`For the quadratic x² − ${a+b}x + ${a*b} = 0, one root is ${a}. What is the other root?`,b,`The factorisation is (x − ${a})(x − ${b}) = 0. The other root is ${b}.`,'quadratic-other-root');
 if(v===5)extensionNumber('maths',10,12,`A right triangle has legs of ${3*a} cm and ${4*a} cm. What is its hypotenuse in cm?`,5*a,`This is a scaled 3–4–5 right triangle. Pythagoras gives a hypotenuse of ${5*a} cm.`,'scaled-pythagoras');
 if(v===6)extensionNumber('science',10,11,`A ${a} kg object increases its speed from rest to ${b} m/s. What is its kinetic energy in joules?`,a*b*b/2,`Using Eₖ = ½mv² gives ½ × ${a} × ${b}² = ${a*b*b/2} J.`,'kinetic-energy');
 if(v===7)extensionNumber('economics',10,12,`A model starts with an index of ${a*100}. It increases by 10%, then falls by 10%. What is the final index?`,a*99,`Successive changes multiply: ${a*100} × 1.10 × 0.90 = ${a*99}. Equal percentage increases and decreases do not cancel.`,'compound-percent');
 if(v===8)extensionNumber('maths',11,13,`For f(x) = ${a}x³, find f′(2).`,12*a,`The derivative is ${3*a}x². At 2 this equals ${3*a} × 4 = ${12*a}.`,'cubic-gradient');
 if(v===9)extensionNumber('maths',11,14,`For the arithmetic sequence with first term ${a} and common difference ${b}, what is the sum of the first 10 terms?`,5*(2*a+9*b),`S₁₀ = 10/2 × [2 × ${a} + 9 × ${b}] = ${5*(2*a+9*b)}.`,'arithmetic-series');
 if(v===10)extensionNumber('chemistry',11,13,`A solution has concentration ${formatNumber(a/10)} mol/L and volume 0.5 L. How many moles of solute are present?`,a/20,`n = cV = ${formatNumber(a/10)} × 0.5 = ${formatNumber(a/20)} mol. The values are mathematical practice quantities, not preparation instructions.`,'amount-solution');
 if(v===11)extensionNumber('science',11,14,`A wave has frequency ${a*10} Hz and wavelength ${b} m. What is its speed in m/s?`,a*b*10,`Wave speed = frequency × wavelength = ${a*10} × ${b} = ${a*b*10} m/s.`,'wave-speed');
 if(v===12)extensionNumber('maths',12,15,`For f(x) = ${a}x³ − ${b}x, find f″(2).`,12*a,`f′(x) = ${3*a}x² − ${b}; f″(x) = ${6*a}x. At x = 2 this gives ${12*a}.`,'second-derivative');
 if(v===13)extensionNumber('maths',12,16,`Evaluate the definite integral of ${3*a}x² from x = 0 to x = ${b}.`,a*b**3,`An antiderivative is ${a}x³. Evaluate the bounds: ${a} × ${b}³ − 0 = ${a*b**3}.`,'cubic-integral');
 if(v===14)extensionNumber('maths',12,17,`For f(x) = ${a}x⁴, find f″(1).`,12*a,`Differentiate twice: f′(x) = ${4*a}x³ and f″(x) = ${12*a}x². At x = 1 the value is ${12*a}.`,'quartic-curvature');
 if(v===15)extensionNumber('science',12,16,`An ideal transformer has ${a*100} primary turns and ${a*200} secondary turns. Its input is ${b*10} V. What is the output voltage in volts?`,b*20,`For an ideal transformer, Vₛ/Vₚ = Nₛ/Nₚ = 2. Therefore Vₛ = 2 × ${b*10} = ${b*20} V.`,'transformer-ratio');
}
QUESTION_COUNT=Object.values(BANK).reduce((n,a)=>n+a.length,0);

for(const year of [10,11,12]){const known=new Set(SENIOR_BANK[year].map(q=>q.prompt));for(const[id,rows]of Object.entries(BANK))for(const q of rows){if(q[8]!==year||known.has(q[0]))continue;const fields={maths:'Mathematics',science:'Science',chemistry:'Chemistry',biology:'Biology',english:'English',economics:'Economics'};const choices=[q[1][q[2]],...q[1].filter((_,i)=>i!==q[2])];addSenior(year,fields[id]||id,q[0],choices,q[3],q[6]||id);known.add(q[0])}}
